def transform(grid):
    out = [row[:] for row in grid]
    for row in out:
        if len(set(row)) <= 1:
            continue
        tail = row[-1]
        start = len(row) - 1
        while start >= 0 and row[start] == tail:
            start -= 1
        tail_len = len(row) - 1 - start
        if tail_len < len(row) - tail_len:
            for j in range(start + 1, len(row)):
                row[j] = 1
    return out

